public class CheckoutTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round2(double x) {
        return Math.round(x * 100) / 100.0;
    }

    public static void main(String[] args) {
        try {
            check("regular: 3 items at 2.50", 7.5, round2(Checkout.total(3, 2.50, Checkout.regular())));
            check("regular: 10 items at 10.00 has no discount", 100.0, round2(Checkout.total(10, 10.00, Checkout.regular())));
            check("bulk: 9 items at 10.00 is below the threshold", 90.0, round2(Checkout.total(9, 10.00, Checkout.bulkDiscount())));
            check("bulk: 10 items at 10.00 gets 10% off", 90.0, round2(Checkout.total(10, 10.00, Checkout.bulkDiscount())));
            check("bulk: 12 items at 1.99 gets 10% off", 21.49, round2(Checkout.total(12, 1.99, Checkout.bulkDiscount())));
            check("bulk: 1 item at 5.00 pays full price", 5.0, round2(Checkout.total(1, 5.00, Checkout.bulkDiscount())));
            check("total delegates to a custom strategy", 42.0, round2(Checkout.total(2, 3.00, (q, u) -> 42.0)));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

