interface PricingStrategy {
    double priceFor(int quantity, double unitPrice);
}

public class Checkout {

    public static PricingStrategy regular() {
        return (quantity, unitPrice) -> quantity * unitPrice;
    }

    public static PricingStrategy bulkDiscount() {
        return (quantity, unitPrice) -> {
            double full = quantity * unitPrice;
            return quantity >= 10 ? full * 0.9 : full;
        };
    }

    public static double total(int qty, double unit, PricingStrategy s) {
        return s.priceFor(qty, unit);
    }
}
